old:
/* PR #2: retain touch movement only in compact/touch landscape layouts. */
@media (max-width: 768px), (max-height: 520px) and (pointer: coarse) {
    body.eb-capture-clean #mobile-controls { display:grid!important; }
}
@media (min-width: 769px) and (min-height: 521px) {
    #mobile-controls, body.eb-capture-clean #mobile-controls { display:none!important; }
}

new:
/* PR #2: keep desktop controls hidden by default; retain touch movement at every size, including hybrids. */
@media (max-width: 768px), (any-pointer: coarse) {
    #mobile-controls, body.eb-capture-clean #mobile-controls { display:grid!important; }
}
